def can_partition(n, m):
    partition = [-1] * n

    def solve(idx):
        if idx == n:
            return True

        for i in range(m):
            current_set = [j + 1 for j in range(idx) if partition[j] == i]

            is_ok = True
            for x in current_set:
                if (idx + 1) - x in current_set:
                    is_ok = False
                    break

            if is_ok:
                partition[idx] = i
                if solve(idx + 1):
                    return True
                partition[idx] = -1
        return False

    return solve(0)

